import { getEnv } from "@/server/env";
import { PUBLIC_MEDIA_KEY } from "@/server/storage/file-rules";

// Public catalog media (product images, GLB previews) from the MEDIA bucket.
// Only keys generated by the upload pipeline are served; keys are random
// UUIDs, so responses are immutable and cached for a year.
export async function GET(_request: Request, { params }: RouteContext<"/media/[...key]">) {
  const { key: parts } = await params;
  const key = parts.join("/");
  if (!PUBLIC_MEDIA_KEY.test(key)) return new Response("Not found", { status: 404 });

  const object = await (await getEnv()).MEDIA.get(key);
  if (!object) return new Response("Not found", { status: 404 });

  const headers = new Headers({
    "Content-Type": object.httpMetadata?.contentType ?? "application/octet-stream",
    "Content-Length": String(object.size),
    "Cache-Control": "public, max-age=31536000, immutable",
    ETag: object.httpEtag,
    "X-Content-Type-Options": "nosniff",
    "Content-Security-Policy": "default-src 'none'; sandbox",
    "Cross-Origin-Resource-Policy": "same-origin",
  });
  return new Response(object.body as unknown as ReadableStream, { headers });
}
